CREATE DATABASE IF NOT EXISTS neuroblackwell CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE neuroblackwell;
CREATE TABLE IF NOT EXISTS experiments (id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id VARCHAR(128) NOT NULL UNIQUE, backend VARCHAR(128) NOT NULL, task VARCHAR(128) NOT NULL, seed BIGINT, parameters JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS metrics (id BIGINT AUTO_INCREMENT PRIMARY KEY, experiment_id BIGINT NOT NULL, name VARCHAR(128) NOT NULL, value DOUBLE NOT NULL, unit VARCHAR(64), FOREIGN KEY(experiment_id) REFERENCES experiments(id));
CREATE TABLE IF NOT EXISTS sources (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(512) NOT NULL, url VARCHAR(1024), source_type VARCHAR(64), provenance TEXT);
CREATE TABLE IF NOT EXISTS equations (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(256) NOT NULL, expression TEXT NOT NULL, domain VARCHAR(256), units VARCHAR(128), source_id BIGINT, FOREIGN KEY(source_id) REFERENCES sources(id));
